-- Read-only verification; expected denied_mobile_grants = 0.
SELECT version,applied_at FROM public.schema_migrations ORDER BY version;
SELECT count(*) AS denied_mobile_grants FROM information_schema.table_privileges
 WHERE table_schema='public' AND grantee IN ('anon','authenticated')
 AND table_name IN ('users','profiles','preferences','sessions','auth_challenges','rate_limits','commands','wallet_entries','holds','rewards','store_transactions','subscriptions','webhook_events','events','event_members','join_requests','waitlist','results','result_confirmations','feedback','rating_history','reliability_history','teams','team_members','team_invites','challenges','tournaments','tournament_members','tournament_fixtures','communities','community_members','venues','venue_slots','bookings','venue_payments','threads','thread_members','blocks','uploads','messages','memories','memory_likes','notifications','outbox','push_devices','support_requests','reports','deletion_requests','audit_log','feature_flags','legal_documents','legal_acceptances','discovery_preferences','oauth_flows','storage_deletions','subscription_windows','job_checkpoints','venue_reviews','message_metadata','thread_member_state','thread_revisions','message_hides','memory_locations','notification_hides','venue_applications','event_locations');
SELECT id,public,file_size_limit,allowed_mime_types FROM storage.buckets WHERE id='matchora-private';
